/*
 * A named learner's programme, for a staff caller (`role:staff` in the
 * security file). `now` is honoured HERE and only here (§0.6): it is the proof
 * seam that pins the assembly to the fixture's instant, and a page never sends it.
 * One hop from the Request node, run on `Received`, so both parameters are set.
 */
const learnerId = String(Inputs.learnerId || '').trim();
const now = String(Inputs.now || '').trim();
if (!learnerId) {
  Outputs.error = 'learnerId is required';
  Outputs.failed();
} else if (now && Number.isNaN(Date.parse(now))) {
  Outputs.error = 'now is not an instant';
  Outputs.failed();
} else {
  Outputs.query = { learnerId, now };
}

/*
 * WHAT A GATED STAFF CALLER MAY READ — `projectForCoach`
 * (src/lib/server/timeline/model.ts). A superset of the learner's: signals and
 * internal notes stay. THE GATE IS THE SECURITY FILE'S (`role:staff`), never
 * this node's — the one thing worse than no gate is two half-gates disagreeing.
 * `unread` is resolved from the coach's side, on the live list and the history.
 */
if (Inputs.payload !== undefined) {
  try {
    const p = Inputs.payload;
    const one = (e) => {
      let out = e;
      if (e.kind === 'note') {
        const { _visibility, ...note } = e.note;
        out = { ...e, note };
      }
      return out.kind === 'message' ? { ...out, unread: out.authorRole !== 'coach' && !out.read } : out;
    };
    Outputs.rows = [{ ...p, entries: p.entries.map(one), history: p.history.map(one) }];
    Outputs.done();
  } catch (e) {
    Outputs.error = String((e && e.message) || e);
    // Logged for the operator; the caller still gets one refusal body (the mcp/auth.ts rule).
    console.error('[dbt:learnerProgramme]', Outputs.error);
    Outputs.failed();
  }
}
